import {
  BrowserRuntime,
  CapabilityRegistry,
  PageObserver,
  setControlValue,
} from '@pagesquire/core';
import type { CapabilityHandler, VerificationHandler } from '@pagesquire/core';
import { PROTOCOL_VERSION } from '@pagesquire/protocol';
import type { ActionCall, JsonObject } from '@pagesquire/protocol';
import {
  AssistantClient,
  ChatNavigationStore,
  createHttpTransport,
  mountWidget,
} from '@pagesquire/client';
// @ts-expect-error Fixture bindings are generated by the build.
import { parameters } from '../../tests/fixtures/dist/bindings.js';
// @ts-expect-error The fixture manifest is shared with Node tests.
import { manifest } from '../../tests/fixtures/capabilities.mjs';

const output = document.querySelector<HTMLPreElement>('#result')!;
const panel = document.querySelector<HTMLElement>('#accessibility-panel')!;
const colorControl =
  document.querySelector<HTMLInputElement>('#heading-color')!;
const fontControl = document.querySelector<HTMLInputElement>('#font-weight')!;
const allowedButton =
  document.querySelector<HTMLButtonElement>('#allowed-button')!;
const search = document.querySelector<HTMLInputElement>('#search')!;
const activities: string[] = [];
const clickBefore = new Map<string, number>();
const inputBefore = new Map<string, number>();
let clickCount = 0;
let inputEvents = 0;

allowedButton.addEventListener('click', () => {
  document.querySelector('#click-count')!.textContent = String(++clickCount);
});
search.addEventListener('input', () => {
  document.querySelector('#input-events')!.textContent = String(++inputEvents);
});
colorControl.addEventListener('input', () => {
  document
    .querySelectorAll<HTMLElement>('main h1, main h2')
    .forEach((element) => {
      element.style.color = colorControl.value;
    });
});
fontControl.addEventListener('input', () => {
  document.body.style.fontWeight = fontControl.value;
});
document.querySelector<HTMLElement>('#destination')!.hidden =
  location.pathname !== '/next.html';

const observer = new PageObserver({
  document,
  allowUrl: (url) => ['/', '/index.html', '/next.html'].includes(url.pathname),
  canInteract: (element, interaction) =>
    interaction === 'click' ? element === allowedButton : element === search,
});

const handlers: Record<string, CapabilityHandler> = {
  'accessibility.set_heading_color': (args, context) => {
    panel.hidden = false;
    setControlValue(
      context.observer.findUnique('#heading-color'),
      args.color as string,
      context.signal,
    );
  },
  'accessibility.set_link_highlight': (args, context) => {
    context.signal.throwIfAborted();
    document
      .querySelector('main')!
      .classList.toggle('links-highlighted', args.enabled as boolean);
  },
  'accessibility.set_font_weight': (args, context) => {
    panel.hidden = false;
    setControlValue(
      context.observer.findUnique('#font-weight'),
      String(args.weight),
      context.signal,
    );
  },
  'browser.click': (args, context) => {
    const target = context.observer.resolveTarget(
      context.call.snapshotId,
      args.targetId as string,
      'click',
    );
    context.signal.throwIfAborted();
    clickBefore.set(context.call.callId, clickCount);
    (target as HTMLElement).click();
  },
  'browser.fill': (args, context) => {
    const target = context.observer.resolveTarget(
      context.call.snapshotId,
      args.targetId as string,
      'fill',
    );
    inputBefore.set(context.call.callId, inputEvents);
    setControlValue(target, args.value as string, context.signal);
  },
  'browser.navigate': async (args, context) => {
    await context.navigate(args.url as string);
  },
  'testing.wait': async (args, context) => {
    const end = Date.now() + (args.milliseconds as number);
    await context.waitFor(() => Date.now() >= end);
  },
  'testing.unverified': () => {},
  'testing.secret_failure': () => {
    throw new Error('super-secret-provider-key');
  },
  'testing.ambiguous': (_args, context) => {
    context.observer.findUnique('.ambiguous');
  },
  'testing.consequential': () => {
    document.body.dataset.unexpectedMutation = 'true';
  },
};

const verifiers: Record<string, VerificationHandler> = {
  'accessibility.set_heading_color.verify': (args) => {
    const sample = document.createElement('span');
    sample.style.color = args.color as string;
    const expected = sample.style.color;
    const headings = [
      ...document.querySelectorAll<HTMLElement>('main h1, main h2'),
    ];
    return {
      verified:
        headings.length > 0 &&
        headings.every(
          (element) => getComputedStyle(element).color === expected,
        ),
      evidence: { color: expected },
    };
  },
  'accessibility.set_link_highlight.verify': (args) => ({
    verified:
      document
        .querySelector('main')!
        .classList.contains('links-highlighted') === args.enabled,
    evidence: { enabled: args.enabled! },
  }),
  'accessibility.set_font_weight.verify': (args) => ({
    verified:
      getComputedStyle(document.body).fontWeight === String(args.weight),
    evidence: { weight: args.weight! },
  }),
  'browser.click.verify': (_args, context) => ({
    verified: clickCount === (clickBefore.get(context.call.callId) ?? -2) + 1,
    evidence: { count: clickCount },
  }),
  'browser.fill.verify': (args, context) => ({
    verified:
      search.value === args.value &&
      inputEvents === (inputBefore.get(context.call.callId) ?? -2) + 1,
    evidence: { inputEventObserved: inputEvents > 0 },
  }),
  'browser.verifyNavigation': (args) => ({
    verified: location.href === new URL(args.url as string, location.href).href,
    evidence: { url: location.href },
  }),
  'testing.wait.verify': () => ({ verified: true }),
  'testing.unverified.verify': () => ({ verified: false }),
  'testing.secret_failure.verify': () => ({ verified: false }),
  'testing.ambiguous.verify': () => ({ verified: false }),
  'testing.consequential.verify': () => ({ verified: false }),
};

const registry = new CapabilityRegistry(manifest, {
  handlers,
  verifiers,
  parameters,
});
const createRuntime = (
  options: { timeoutMs?: number; maxActions?: number } = {},
) =>
  new BrowserRuntime({
    observer,
    registry,
    ...options,
    onActivityChange: (activity) => {
      activities.push(activity);
      document.querySelector('#activity')!.textContent = activity;
    },
  });
let runtime = createRuntime();

const makeCall = (
  capabilityId: string,
  args: JsonObject,
  callId: string = crypto.randomUUID(),
): ActionCall => ({
  protocolVersion: PROTOCOL_VERSION,
  callId,
  capabilityId,
  snapshotId: runtime.observe().id,
  parameters: args,
});

const demo = {
  get runtime() {
    return runtime;
  },
  observer,
  registry,
  activities,
  makeCall,
  call: async (capabilityId: string, args: JsonObject, callId?: string) => {
    const result = await runtime.execute(makeCall(capabilityId, args, callId));
    output.textContent = JSON.stringify(result, null, 2);
    return result;
  },
  configure: (options: { timeoutMs?: number; maxActions?: number }) => {
    runtime = createRuntime(options);
  },
  resumed: document.querySelector('meta[name="pagesquire-endpoint"]')
    ? undefined
    : await runtime.resumeNavigation(),
};
if (demo.resumed) output.textContent = JSON.stringify(demo.resumed, null, 2);
Object.assign(window, { pagesquireDemo: demo });

const endpoint = document.querySelector<HTMLMetaElement>(
  'meta[name="pagesquire-endpoint"]',
)?.content;
if (endpoint) {
  const emotions: string[] = [];
  const client = new AssistantClient({
    runtime,
    navigationStore: new ChatNavigationStore(sessionStorage),
    transport: createHttpTransport({
      endpoint,
      baseUrl: location.href,
      csrfToken: () =>
        document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')!
          .content,
    }),
    onEmotionChange: (emotion) => {
      emotions.push(emotion);
    },
  });
  const dispose = mountWidget(
    document.querySelector<HTMLElement>('#chat-widget')!,
    client,
    { title: 'PageSquire · server demo' },
  );
  Object.assign(window, { pagesquireChat: { client, dispose, emotions } });
  await client.resumeNavigation();
}

const bind = (selector: string, capabilityId: string, args: JsonObject) => {
  document.querySelector(selector)!.addEventListener('click', () => {
    void demo.call(capabilityId, args).catch(() => {
      output.textContent = 'The action could not be started.';
    });
  });
};
bind('#try-heading', 'accessibility.set_heading_color', { color: '#ff0000' });
bind('#try-links', 'accessibility.set_link_highlight', { enabled: true });
bind('#try-font', 'accessibility.set_font_weight', { weight: 700 });
bind('#try-navigation', 'browser.navigate', { url: '/next.html' });
document
  .querySelector('#cancel')!
  .addEventListener('click', () => runtime.cancel());
